import sys, os; sys.path.insert(0, os.path.dirname(os.path.dirname(__file__)))
from dsl import *
U("s2-u12")
C = "A1-A2"

L(1, "Como está o tempo?", "Het regent, de zon schijnt, het waait.",
  ["Descrever o tempo com verbos impessoais"],
  vocab=[V("v-regenen","regenen","chover","verb",note="Het regent = está a chover."), V("v-schijnen","schijnen","brilhar","verb",note="De zon schijnt = está sol."),
         V("v-waaien","waaien","fazer vento","verb",note="Het waait = está vento."), V("v-sneeuwen","sneeuwen","nevar","verb"),
         V("v-bewolkt","bewolkt","nublado","adjective"), V("v-regen","regen","chuva","noun","de")],
  ex=[("Het regent.","Está a chover."),("De zon schijnt.","Está sol."),("Het waait hard.","Está muito vento."),("Het is bewolkt.","Está nublado.")],
  gram=[G("g-weer-het","O tempo com «het»","Para o tempo usa-se **het** como sujeito: *het regent*, *het waait*, *het sneeuwt*, *het is koud*. Exceção: *de zon schijnt*. Pergunta: **Wat voor weer is het?** / **Hoe is het weer?**",
    [("Het gaat regenen.","Vai chover."),("Wat voor weer is het in Lissabon?","Como está o tempo em Lisboa?")],
    "Em português «chove» não tem sujeito; em neerlandês é obrigatório: «het regent».")],
  review=["v-weer","v-koud","v-warm","v-zon","v-het-pron"],
  cefr=C, exs=[
    MA([("regenen","chover"),("waaien","fazer vento"),("sneeuwen","nevar"),("bewolkt","nublado"),("regen","chuva")], "Tempo.", ["v-regenen","v-waaien","v-sneeuwen","v-bewolkt","v-regen"]),
    TR("pt-nl","Está a chover.", ["Het regent"], "het + verbo.", ["v-regenen"]),
    TR("pt-nl","Está sol.", ["De zon schijnt","Het is zonnig"], "de zon schijnt.", ["v-schijnen"]),
    TR("nl-pt","Het waait hard vandaag.", ["Hoje está muito vento","Está muito vento hoje"], "hard waaien = muito vento.", ["v-waaien"]),
    FE(["Het","regenen","vandaag."], 1, "regent", "Com «het»: het regent.", ["v-regenen"]),
    MC("Como se pergunta como está o tempo?", ["*Wat voor weer is het?","Hoe laat is het?|Isso é «que horas são».","Hoe gaat het?|Isso é «como estás»."], "Wat voor weer is het?", ["v-weer"]),
    FB("In januari ___ het soms.", ["sneeuwt"], "sneeuwen → het sneeuwt.", ["v-sneeuwen"], choices=["sneeuwt","schijnt","bewolkt"], tr="Em janeiro às vezes neva."),
    LI("Het is bewolkt en het regent.", ["Het is bewolkt en het regent"], "Está nublado e a chover.", "Dia típico neerlandês.", ["v-bewolkt","v-regenen"]),
    AR("regen","a chuva","de", "«De regen».", ["v-regen"]),
    WO("Amanhã vai chover.", ["Morgen","gaat","het","regenen"], "gaan + infinitivo = futuro próximo.", ["v-regenen"], alt=["Het gaat morgen regenen"]),
  ], diff=2, mins=5)

L(2, "As estações", "lente, zomer, herfst, winter.",
  ["Dizer as estações e o que acontece em cada uma"],
  vocab=[V("v-lente","lente","primavera","noun","de",note="Também «het voorjaar»."), V("v-zomer","zomer","verão","noun","de"),
         V("v-herfst","herfst","outono","noun","de",note="Também «het najaar»."), V("v-winter","winter","inverno","noun","de"),
         V("v-seizoen","seizoen","estação (do ano)","noun","het","seizoenen")],
  ex=[("In de zomer is het warm.","No verão faz calor."),("In de herfst waait het veel.","No outono há muito vento."),("Mijn lievelingsseizoen is de lente.","A minha estação preferida é a primavera.")],
  gram=[G("g-in-de-seizoen","In de + estação","Com as estações usa-se **in de**: *in de zomer*, *in de winter*. (Com os meses é só **in**: *in juli*.)",
    [("In de lente bloeien de tulpen.","Na primavera florescem as túlipas.")])],
  review=["v-koud","v-warm","v-regenen","v-lievelings"],
  cefr=C, exs=[
    MA([("lente","primavera"),("zomer","verão"),("herfst","outono"),("winter","inverno")], "Estações.", ["v-lente","v-zomer","v-herfst","v-winter"]),
    AR("seizoen","a estação do ano","het", "«Het seizoen».", ["v-seizoen"]),
    TR("pt-nl","No verão faz calor.", ["In de zomer is het warm","Het is warm in de zomer"], "in de zomer.", ["v-zomer","v-warm"]),
    TR("nl-pt","In de herfst waait het veel.", ["No outono [há|faz] muito vento"], "in de herfst.", ["v-herfst","v-waaien"]),
    FE(["In","winter","is","het","koud."], 1, "de winter", "Com estações: in de winter.", ["v-winter"]),
    MC("Quando florescem as túlipas nos Países Baixos?", ["*In de lente","In de winter|Faz frio demais.","In de herfst|As túlipas florescem em abril/maio."], "Primavera: de lente.", ["v-lente"]),
    FB("Mijn lievelings___ is de zomer.", ["seizoen"], "lievelingsseizoen.", ["v-seizoen"], choices=["seizoen","maand","dag"], tr="A minha estação preferida é o verão."),
    LI("In de winter is het donker en koud.", ["In de winter is het donker en koud"], "No inverno está escuro e frio.", "No inverno escurece cedo.", ["v-winter"]),
    WO("No outono chove muito.", ["In","de","herfst","regent","het","veel"], "Inversão.", ["v-herfst","v-regenen"]),
    CO("text","O clima neerlandês", "Nederland heeft een zeeklimaat. De zomers zijn niet heel warm: meestal twintig tot vijfentwintig graden. De winters zijn niet heel koud, maar het regent en waait veel. Sneeuw is niet zo vaak.",
       [("Como são os verões?", ["*Não muito quentes","Muito quentes","Muito frios"]),("O que é frequente no inverno?", ["*Chuva e vento","Neve todos os dias","Sol"])],
       "graden = graus; zeeklimaat = clima marítimo.", ["v-zomer","v-winter"]),
  ], diff=2, mins=5)

L(3, "Temperaturas e previsão", "graden, het weerbericht, morgen wordt het…",
  ["Perceber uma previsão do tempo simples"],
  vocab=[V("v-graad","graad","grau","noun","de","graden"), V("v-weerbericht","weerbericht","previsão do tempo","noun","het"),
         V("v-worden","worden","tornar-se|ficar","verb",note="ik word, jij wordt, hij wordt. Morgen wordt het warm = amanhã vai estar calor."),
         V("v-buien","bui","aguaceiro","noun","de","buien"), V("v-zonnig","zonnig","soalheiro","adjective")],
  ex=[("Het is vijftien graden.","Estão quinze graus."),("Morgen wordt het zonnig.","Amanhã vai estar sol."),("Er zijn buien in het noorden.","Há aguaceiros no norte.")],
  gram=[G("g-worden-tempo","Worden para o futuro do tempo","**worden** (tornar-se) usa-se muito para falar do tempo que vem: *morgen **wordt** het warm* (amanhã vai ficar quente). Também *het wordt donker* (está a escurecer).",
    [("Het wordt koud.","Vai arrefecer."),("Het wordt laat.","Está a ficar tarde.")])],
  review=["v-morgen","v-warm","v-koud","v-regenen","v-weer"],
  cefr=C, exs=[
    MA([("graad","grau"),("weerbericht","previsão do tempo"),("bui","aguaceiro"),("zonnig","soalheiro")], "Previsão.", ["v-graad","v-weerbericht","v-buien","v-zonnig"]),
    TR("pt-nl","Estão vinte graus.", ["Het is twintig graden","Het is 20 graden"], "graad → graden.", ["v-graad"]),
    TR("pt-nl","Amanhã vai estar sol.", ["Morgen wordt het zonnig","Het wordt morgen zonnig"], "worden + adjetivo.", ["v-worden","v-zonnig"]),
    CJ("worden","het","Morgen ___ het koud.", ["wordt"], "worden → het wordt.", ["v-worden"]),
    AR("weerbericht","a previsão do tempo","het", "bericht → het.", ["v-weerbericht"]),
    LI("Er zijn buien in het noorden.", ["Er zijn buien in het noorden"], "Há aguaceiros no norte.", "het noorden = o norte.", ["v-buien"]),
    FE(["Het","is","tien","graad."], 3, "graden", "Plural depois de número > 1: graden.", ["v-graad"]),
    FB("Het ___ donker om vijf uur in december.", ["wordt"], "Começa a escurecer.", ["v-worden"], choices=["wordt","is wordt","regent"], tr="Em dezembro escurece às cinco."),
    CO("text","Previsão", "Weerbericht voor morgen: in de ochtend is het bewolkt, met hier en daar een bui. In de middag schijnt de zon. De temperatuur: zestien graden. Het waait weinig.",
       [("Como estará a manhã?", ["*Nublada, com alguns aguaceiros","Com muito sol","Com neve"]),("Que temperatura?", ["*16 graus","6 graus","26 graus"])],
       "hier en daar = aqui e ali.", ["v-weerbericht","v-graad"]),
    TR("nl-pt","Het wordt laat.", ["Está a ficar tarde","Já é tarde"], "worden = tornar-se.", ["v-worden"]),
  ], diff=2, mins=6)

L(4, "Falar do tempo (small talk)", "O tema de conversa preferido dos neerlandeses.",
  ["Fazer conversa de circunstância sobre o tempo"],
  vocab=[V("v-heerlijk","heerlijk","maravilhoso|delicioso","adjective"), V("v-vreselijk","vreselijk","horrível","adjective"),
         V("v-nat","nat","molhado","adjective"), V("v-paraplu","paraplu","guarda-chuva","noun","de","paraplu's")],
  ex=[("Lekker weertje, hè?","Está um tempinho bom, não está?"),("Wat een vreselijk weer!","Que tempo horrível!"),("Neem een paraplu mee.","Leva um guarda-chuva."),("Ik ben helemaal nat!","Estou todo molhado!")],
  gram=[G("g-small-talk-weer","Small talk","Falar do tempo é a conversa de circunstância mais comum: no elevador, na loja, com vizinhos. Fórmulas típicas: *Lekker weertje, hè?* / *Wat een weer!* / *Het wordt eindelijk lente!* (Finalmente chega a primavera!)",
    [("Eindelijk zon!","Finalmente sol!")])],
  review=["v-he","v-lekker","v-weer","v-regenen"],
  cefr=C, exs=[
    MA([("heerlijk","maravilhoso"),("vreselijk","horrível"),("nat","molhado"),("paraplu","guarda-chuva")], "Conversa sobre o tempo.", ["v-heerlijk","v-vreselijk","v-nat","v-paraplu"]),
    DL([("Vizinha","Lekker weertje, hè?","Está um tempinho bom, não está?"),("Você","")], ["*Ja, heerlijk! Eindelijk zon.","Nee, ik ben weer.|Não faz sentido.","Ja, ik heb een paraplu.|Não combina."], "Concordar com entusiasmo.", ["v-heerlijk"]),
    TR("pt-nl","Que tempo horrível!", ["Wat een vreselijk weer"], "het weer + een → vreselijk.", ["v-vreselijk"]),
    TR("nl-pt","Neem een paraplu mee.", ["Leva um guarda-chuva"], "meenemen = levar.", ["v-paraplu"]),
    FE(["Wat","een","vreselijke","weer!"], 2, "vreselijk", "het weer + een → sem -e.", ["v-vreselijk"]),
    LI("Ik ben helemaal nat!", ["Ik ben helemaal nat"], "Estou todo molhado!", "helemaal = completamente.", ["v-nat"]),
    FB("Het regent: neem je ___ mee!", ["paraplu"], "Para a chuva: guarda-chuva.", ["v-paraplu"], choices=["paraplu","zonnebril","jas"], tr="Está a chover: leva o guarda-chuva!"),
    EX("Lekker weertje, hè?", "Saboroso tempinho, não?", "O que quer dizer?", ["*Está um tempo agradável, não está?","A comida está boa?|«lekker» aqui refere-se ao tempo.","Está calor demais?|É um comentário positivo."], "lekker weer = tempo agradável.", ["v-lekker"]),
    AR("paraplu","o guarda-chuva","de", "«De paraplu».", ["v-paraplu"]),
    WO("Finalmente está sol!", ["Eindelijk","schijnt","de","zon!"], "Inversão.", ["v-schijnen"]),
  ], diff=2, mins=5)

L(5, "Tempo e planos", "Revisão: o tempo decide o que fazemos.",
  ["Ligar o tempo a planos com als e dus"],
  ex=[("Als het mooi weer is, gaan we naar het strand.","Se estiver bom tempo, vamos à praia.")],
  review=["v-regenen","v-zonnig","v-worden","v-zomer","v-winter","v-paraplu","v-dus","v-weer"],
  cefr=C, exs=[
    TR("nl-pt","Als het regent, blijven we thuis.", ["Se chover, ficamos em casa"], "als = se (verbo para o fim + inversão: veremos mais tarde).", ["v-regenen"]),
    TR("pt-nl","Está a chover, por isso fico em casa.", ["Het regent(,) dus ik blijf thuis","Het regent(,) dus blijf ik thuis"], "dus.", ["v-regenen","v-dus"]),
    MC("Está sol e 25 graus. Qual é o plano mais lógico?", ["*Naar het strand gaan","Een paraplu kopen|Não chove.","Sneeuwballen gooien|Não há neve."], "strand = praia.", ["v-zonnig"]),
    FE(["Morgen","worden","het","warm."], 1, "wordt", "het wordt.", ["v-worden"]),
    LI("Wat voor weer wordt het morgen?", ["Wat voor weer wordt het morgen"], "Como vai estar o tempo amanhã?", "worden para o futuro.", ["v-worden"]),
    CO("dialogue","Planos de sábado", "Eva: Zullen we zaterdag gaan fietsen?\nTom: Goed idee! Maar wat zegt het weerbericht?\nEva: Zaterdag wordt het zonnig en twintig graden.\nTom: Perfect! En zondag?\nEva: Zondag gaat het regenen.\nTom: Dan gaan we zondag naar het museum.",
       [("Que tempo vai fazer no sábado?", ["*Sol e vinte graus","Chuva","Neve"]),("O que fazem no domingo?", ["*Vão ao museu","Andam de bicicleta","Ficam em casa"])],
       "Os planos dependem do tempo.", ["v-zonnig","v-regenen"]),
    MA([("Het regent.","Está a chover."),("Het waait.","Está vento."),("De zon schijnt.","Está sol."),("Het sneeuwt.","Está a nevar.")], "Verbos do tempo.", ["v-regenen","v-waaien","v-schijnen","v-sneeuwen"]),
    WO("No inverno faz frio, portanto levo um casaco grosso.", ["In","de","winter","is","het","koud,","dus","draag","ik","een","dikke","jas"], "dus + inversão.", ["v-winter","v-dus"]),
    FB("In de ___ gaan we naar het strand.", ["zomer"], "No verão, praia.", ["v-zomer"], choices=["zomer","winter","herfst"], tr="No verão vamos à praia."),
    SW("Descreva o tempo de hoje onde está e diga o que vai fazer por causa disso.", ["Het regent(,) dus ik blijf thuis","Het is zonnig en warm(,) dus ik ga fietsen"],
       ["Descreve o tempo com «het»","Liga ao plano com «dus» ou «want»","Verbo em 2.º lugar"], 6, "Modelo: «Het is zonnig en warm, dus ik ga fietsen.»", ["v-weer"]),
  ], diff=2, mins=6)

W()
